"""reports/maintenance_policy.md with tables and figures (generated by `cmapss policy`; do not edit)."""

from __future__ import annotations

from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

from cmapss_pm.config import Config
from cmapss_pm.policy.run import POLICIES, PolicyRun


def _md(df: pd.DataFrame, floatfmt: str = ".3f") -> str:
    return str(df.astype(object).to_markdown(index=False, floatfmt=floatfmt)) if len(df) else "_none_"


def _figures(run: PolicyRun, cfg: Config) -> list[Path]:
    out = cfg.path("figures_dir")
    out.mkdir(parents=True, exist_ok=True)
    cost = {str(k): float(v) for k, v in zip(run.summary["policy"], run.summary["cost_per_engine"], strict=True)}
    paths = []
    fig, ax = plt.subplots(figsize=(8, 4))
    c = run.curve
    ax.plot(c.threshold, c.cost_per_engine, color="C0", label="model policy")
    for name, style in [("fixed_interval", "--"), ("run_to_failure", ":"), ("perfect_information", "-.")]:
        ax.axhline(cost[name], color="0.4", ls=style, lw=1, label=name.replace("_", " "))
    ax.axvline(run.threshold, color="C3", lw=1, label=f"chosen threshold {run.threshold:.3f}")
    ax.set_xscale("log")
    ax.set_xlabel("threshold on P(fail within N) (log scale)")
    ax.set_ylabel("mean cost per engine (assumed units)")
    ax.set_title("Expected cost by threshold, training engines (baselines cross-fitted)")
    ax.legend(fontsize=7)
    fig.tight_layout()
    paths.append(out / "policy_cost_by_threshold.png")
    fig.savefig(paths[-1], dpi=120)
    plt.close(fig)

    fig, ax = plt.subplots(figsize=(8, 4))
    planned_cost = [
        float(np.mean(np.where(~run.base.outcomes[p].failed, run.base.outcomes[p].cost, 0.0))) for p in POLICIES
    ]
    failure_cost = [
        float(np.mean(np.where(run.base.outcomes[p].failed, run.base.outcomes[p].cost, 0.0))) for p in POLICIES
    ]
    labels = [p.replace("_", "\n") for p in POLICIES]
    ax.bar(labels, planned_cost, label="planned visits incl. lost life", color="C0")
    ax.bar(labels, failure_cost, bottom=planned_cost, label="in-service failures", color="C3")
    ax.set_ylabel("mean cost per engine (assumed units)")
    ax.set_title("Where the cost comes from (cross-fitted, training engines)")
    ax.legend(fontsize=8)
    fig.tight_layout()
    paths.append(out / "policy_cost_breakdown.png")
    fig.savefig(paths[-1], dpi=120)
    plt.close(fig)
    return paths


def write_policy_report(run: PolicyRun, cfg: Config) -> Path:
    tables = cfg.path("tables_dir")
    tables.mkdir(parents=True, exist_ok=True)
    for name, df in [
        ("policy_summary", run.summary),
        ("policy_by_dataset", run.by_dataset),
        ("policy_scenarios", run.scenarios),
        ("policy_test_check", run.test),
        ("policy_cost_curve", run.curve),
    ]:
        df.to_csv(tables / f"{name}.csv", index=False)
    figs = _figures(run, cfg)
    m = run.meta
    cost = {str(k): float(v) for k, v in zip(run.summary["policy"], run.summary["cost_per_engine"], strict=True)}
    best = "fixed_interval" if cost["fixed_interval"] <= cost["run_to_failure"] else "run_to_failure"
    saving = cost[best] - cost["model"]
    attainable = cost[best] - cost["perfect_information"]
    by_ds = run.by_dataset[run.by_dataset.policy.isin(["model", "fixed_interval"])][
        ["dataset", "policy", "engines", "failures", "mean_lost_cycles_when_planned", "cost_per_engine"]
    ]
    intervals = pd.DataFrame(m["fixed_interval_by_fold"]).T.rename_axis("fold").reset_index()
    reports = cfg.path("reports_dir")
    fig_list = ", ".join(f"`{p.relative_to(reports).as_posix()}`" for p in figs)
    costs = m["costs"]
    text = f"""<!-- GENERATED by `cmapss policy` - do not edit by hand. -->
# Maintenance policy

**Estimates under assumptions, on simulated data.** Costs are assumptions (`business` in `configs/config.yaml`:
in-service failure {costs["unplanned"]:g}, planned visit {costs["planned"]:g}, {costs["lost_life"]:g} per cycle of
life given up), NASA C-MAPSS is a simulation, and no real fleet cost data exist here. Design: D-024, D-025.

**Rule:** book a shop visit when the calibrated P(fail within {m["horizon"]} cycles) reaches
**{run.threshold:.4f}**; the visit happens {m["lead_time"]} cycles later (lead time). Champion model version
{m["champion_version"]} (gold Delta version {m["gold_delta_version"]}, feature spec `{m["feature_spec_version"]}`). The
threshold is stored in `artifacts/policy.json` and as tag `policy_threshold` on the model version.

## 1. Policies compared (709 training engines, full lives)

Every training engine runs to failure, so each policy's outcome is known. The decision signal is the out-of-fold
probability (no engine is scored by a model that saw it). The model threshold and the fixed intervals (per
dataset) are chosen on four folds and applied to the fifth (cross-fitted), so the costs below are not inflated by
choosing and scoring on the same engines.

{_md(run.summary)}

- Saving of the model policy against the best baseline ({best.replace("_", " ")}):
  **{saving:.1f} per engine ({saving / cost[best]:.1%})**, which is
  {saving / attainable:.0%} of the saving a perfect-information policy would reach.
- Thresholds chosen per fold: {", ".join(f"{v:.4f}" for v in m["threshold_by_fold"].values())}.

By dataset (model vs fixed interval):

{_md(by_ds)}

Fixed-interval removal cycle chosen per fold and dataset:

{_md(intervals, ".0f")}

## 2. Sensitivity (each row re-chooses thresholds and intervals, cross-fitted)

One assumption varied at a time around the configured case; horizon rows retrain the classifier for that N with the
lead time unchanged; lead-time rows set N equal to the lead time. `share_of_attainable_saving` = model saving /
perfect-information saving, both against the best baseline.

{_md(run.scenarios)}

## 3. Holdout check on the official test engines

The served rule applied to the 707 test engines with the champion's probabilities. Test engines stop before
failure, so an outcome is known only if the rule fires inside the observed window, or if the engine is already
within the lead time of failure at its last observed cycle without an alert (a certain failure). The rest are
censored.

{_md(run.test)}

Figures: {fig_list}.
"""
    path = reports / "maintenance_policy.md"
    path.write_text(text, encoding="utf-8")
    return path
